-- Insert farms
INSERT INTO farms (id, name, description, location, image_url) VALUES
  ('f1e2d3c4-0001-4000-8000-000000000001', 'FreshFields Farm', 'FreshFields Farm is a modern, eco‑friendly farm dedicated to growing high‑quality produce using sustainable methods. Located in the heart of the countryside, FreshFields focuses on fresh vegetables, leafy greens, and seasonal crops grown without harmful chemicals.', 'Edinburgh, Scotland', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Church_Farm%2C_Stockton%2C_Norfolk_-_geograph.org.uk_-_1968544.jpg/500px-Church_Farm%2C_Stockton%2C_Norfolk_-_geograph.org.uk_-_1968544.jpg'),
  ('f1e2d3c4-0002-4000-8000-000000000002', 'Sunny Orchard Co.', 'Sunny Orchard Co. has been cultivating premium fruits for over three generations. Their orchards are known for exceptionally sweet apples, pears, and stone fruits grown in fertile valleys with optimal sunlight.', 'Kent, England', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Apple_Trees_in_Blossom%2C_Pomona_Farm_-_geograph.org.uk_-_293333.jpg/500px-Apple_Trees_in_Blossom%2C_Pomona_Farm_-_geograph.org.uk_-_293333.jpg'),
  ('f1e2d3c4-0003-4000-8000-000000000003', 'Green Valley Growers', 'Green Valley Growers specialises in vine-ripened tomatoes, crisp cucumbers, and vibrant bell peppers. Their polytunnel‑grown produce delivers consistent quality year‑round.', 'Cornwall, England', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Polytunnel_Balhungie.jpg/500px-Polytunnel_Balhungie.jpg'),
  ('f1e2d3c4-0004-4000-8000-000000000004', 'Berry Patch Farm', 'Berry Patch Farm is a family‑run farm nestled in the rolling hills of Wales. They grow strawberries, raspberries, blueberries, and blackberries using traditional methods that maximise natural flavour.', 'Cardigan, Wales', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Garden_strawberry_%28Fragaria_%C3%97_ananassa%29_single2.jpg/500px-Garden_strawberry_%28Fragaria_%C3%97_ananassa%29_single2.jpg'),
  ('f1e2d3c4-0005-4000-8000-000000000005', 'Tropical Grove', 'Tropical Grove sources the finest exotic fruits from around the world. From sweet mangoes to fragrant dragon fruit, every piece is hand‑selected at peak ripeness.', 'Global Suppliers', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Bananal_REFON.jpg/960px-Bananal_REFON.jpg');

