  ('a1b2c3d4-0001-4000-8000-000000000001', 'Root Vegetables', 'root-vegetables', 'Freshly harvested root vegetables — carrots, potatoes, beets, and more.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/CarrotDiversityLg.jpg/500px-CarrotDiversityLg.jpg'),
  ('a1b2c3d4-0002-4000-8000-000000000002', 'Fruits', 'fruits', 'Sweet and juicy fruits picked at peak ripeness.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Fruit_Platter-_Seasonal_Fruits.jpg/500px-Fruit_Platter-_Seasonal_Fruits.jpg'),
  ('a1b2c3d4-0003-4000-8000-000000000003', 'Leafy Greens', 'leafy-greens', 'Crisp, nutrient-packed leafy greens for salads and cooking.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Spinach_leaves.jpg/960px-Spinach_leaves.jpg'),
  ('a1b2c3d4-0004-4000-8000-000000000004', 'Herbs', 'herbs', 'Aromatic fresh herbs to elevate any dish.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Garden_of_herbs.jpg/500px-Garden_of_herbs.jpg'),
  ('a1b2c3d4-0005-4000-8000-000000000005', 'Berries', 'berries', 'Plump, flavourful berries bursting with freshness.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Berries_%28USDA_ARS%29.jpg/500px-Berries_%28USDA_ARS%29.jpg'),
  ('a1b2c3d4-0006-4000-8000-000000000006', 'Vegetables', 'vegetables', 'Everyday fresh vegetables for all your cooking needs.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Dijon_Covered_Market_%2846%29.jpg/500px-Dijon_Covered_Market_%2846%29.jpg');

